def index_tree(n):
    levels = [ [1]*n ]

    size = WIDTH
    while size < n:
        m, r = n // size, n % size
        levels.append( [size]*m + ([r] if r > 0 else []) )
        size *= WIDTH

    return levels

def dec_index(levels, i):
    for level in levels:
        level[i] -= 1
        i //= WIDTH

def find_pos(levels, pos):
    i, l = 0, len(levels) - 1

    total = 0
    while True:
        level = levels[l]
        while total + level[i] < pos:
            total += level[i]
            i += 1

        if l == 0: return i
        i *= WIDTH
        l -= 1


