            self.size[px] += self.size[py]

    def same(self, x, y):
        return self.find(x) == self.find(y)

    def connectedNum(self, x):
        return self.size[self.find(x)]

    def component_NUM(self):
        par = set()
        for i in self.parent:
            par.add(self.find(i))
        return len(par)


