				elif c1.in_touches(c2) or c1.ex_touches(c2) or c2.in_touches(c1):
					return 7 - any(c2.is_on(p) for p in c0_x_c1)

				else:  # if c1.contains(c2) or c2.contains(c1) or c1.not_intersects(c2):
					return 6

		return 4

	return 0


