#@profile
def insert(heap, val):
    idx = len(heap)
    heap.append(val)

    while idx > 0:
        p = (idx - 1) >> 1

        if heap[p] <= heap[idx]: break

        heap[p], heap[idx] = heap[idx], heap[p]

        idx = p

#@profile
def removeMin(heap):
    last = heap.pop()

    L = len(heap)

    if L == 0: return
    heap[0] = last
