         for i in range(m):
             for j in range(n):
                 heights[j] = heights[j] + 1 if matrix[i][j] == '1' else 0
             stack = [-1]
             for i in range(n + 1):
                 while heights[i] < heights[stack[-1]]:
                     h = heights[stack.pop()]
                     w = i - stack[-1] - 1
                     ans = max(ans, w*h)
